INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die technische Machbarkeit immer von finanziellen Ressourcen abhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Technologie kann unabhängig geprüft werden"}, {"text": "Ja", "correct": false, "because": "Nicht primär finanzabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist für die technische Machbarkeit eines Projekts entscheidend?', 3, '[{"text": "Verfügbarkeit der Technologie", "correct": true, "because": "Bestimmt Umsetzbarkeit"}, {"text": "Farbe der Geräte", "correct": false, "because": "Kein Einfluss"}, {"text": "Marketingstrategie", "correct": false, "because": "Nicht technisch relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Technische Machbarkeit prüft die Umsetzbarkeit mit vorhandener Technik. b) Sie berücksichtigt nur die Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technik im Fokus, nicht Kosten"}, {"text": "Beides stimmt", "correct": false, "because": "Kosten sind wirtschaftlich"}, {"text": "Nur b) stimmt", "correct": false, "because": "Technik ist zentral"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Faktor solltest du bei der technischen Machbarkeit eines Softwareprojekts priorisieren?', 4, '[{"text": "Kompatibilität mit bestehenden Systemen", "correct": true, "because": "Sichert Integration"}, {"text": "Design der Benutzeroberfläche", "correct": false, "because": "Sekundär"}, {"text": "Farbschema", "correct": false, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die technische Machbarkeit ohne Prototypen geprüft werden?', 2, '[{"text": "Ja", "correct": true, "because": "Theoretische Analyse möglich"}, {"text": "Nein", "correct": false, "because": "Prototypen nicht zwingend nötig"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die technische Machbarkeit immer von der Verfügbarkeit neuer Technologien abhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Bestehende Technologien können ausreichen"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der technischen Machbarkeit entscheidend?', 3, '[{"text": "Verfügbarkeit von Ressourcen", "correct": true, "because": "Bestimmt Umsetzbarkeit"}, {"text": "Farbe der Geräte", "correct": false, "because": "Kein Einfluss"}, {"text": "Markenname", "correct": false, "because": "Sekundär zur Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Technische Machbarkeit prüft, ob ein Projekt umsetzbar ist. b) Sie berücksichtigt nur die Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Machbarkeit ist technisch, Kosten separat"}, {"text": "Beides stimmt", "correct": false, "because": "Kosten sind wirtschaftlich"}, {"text": "Nur b) stimmt", "correct": false, "because": "Technische Prüfung zentral"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium solltest du bei der technischen Machbarkeit eines Softwareprojekts priorisieren?', 4, '[{"text": "Technologische Kompatibilität", "correct": true, "because": "Sichert Integration"}, {"text": "Design der Benutzeroberfläche", "correct": false, "because": "Sekundär"}, {"text": "Farbe der Hardware", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt technisch machbar sein, ohne aktuelle Technologien zu nutzen?', 2, '[{"text": "Ja", "correct": true, "because": "Ältere Technologien können genügen"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend neu nötig"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
